-- =============================================================================================
-- Hand-written below this line: integrity rules, the online admission backstop, immutability,
-- the append-only access log, row-level security and grants for visitors.
-- See docs/architecture/DATA_MODEL.md section 5 (Visitors and access).
-- Times are instants (timestamptz); the API converts the property's local times.
-- =============================================================================================

-- ---------------------------------------------------------------------------------------------
-- visitor_invitations
-- ---------------------------------------------------------------------------------------------
ALTER TABLE "visitor_invitations" ADD CONSTRAINT "visitor_invitations_name_trimmed"
  CHECK ("visitor_name" = btrim("visitor_name") AND length("visitor_name") BETWEEN 1 AND 200);
ALTER TABLE "visitor_invitations" ADD CONSTRAINT "visitor_invitations_phone_e164"
  CHECK ("visitor_phone" IS NULL OR "visitor_phone" ~ '^\+[1-9][0-9]{6,14}$');
ALTER TABLE "visitor_invitations" ADD CONSTRAINT "visitor_invitations_plate_normalised"
  CHECK ("vehicle_plate" IS NULL OR "vehicle_plate" ~ '^[A-Z0-9-]{2,15}$');
-- A window ends after it starts and lasts at most 31 days (longer access is not a visit).
ALTER TABLE "visitor_invitations" ADD CONSTRAINT "visitor_invitations_window"
  CHECK ("valid_until" > "valid_from" AND "valid_until" - "valid_from" <= interval '31 days');
ALTER TABLE "visitor_invitations" ADD CONSTRAINT "visitor_invitations_max_entries"
  CHECK ("max_entries" BETWEEN 1 AND 50);
ALTER TABLE "visitor_invitations" ADD CONSTRAINT "visitor_invitations_revoke_consistent"
  CHECK (("status" = 'REVOKED') = ("revoked_at" IS NOT NULL)
         AND ("revoked_by_user_id" IS NULL OR "revoked_at" IS NOT NULL));

-- Revocation is final, and an invitation never moves to another property, unit or creator.
CREATE FUNCTION app_visitor_invitation_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF OLD."status" = 'REVOKED' THEN
    RAISE EXCEPTION 'visitor invitation % is revoked and cannot change', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."organisation_id" <> OLD."organisation_id" OR NEW."property_id" <> OLD."property_id"
     OR NEW."unit_id" <> OLD."unit_id" OR NEW."created_by_user_id" <> OLD."created_by_user_id" THEN
    RAISE EXCEPTION 'visitor invitation % cannot move or change its creator', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "visitor_invitations_guard"
  BEFORE UPDATE ON "visitor_invitations"
  FOR EACH ROW EXECUTE FUNCTION app_visitor_invitation_guard();

-- ---------------------------------------------------------------------------------------------
-- visitor_passes: hashes only; at most one live pass per invitation; codes unique per property
-- among live passes (a code is short, so it must not be ambiguous at the gate).
-- ---------------------------------------------------------------------------------------------
ALTER TABLE "visitor_passes" ADD CONSTRAINT "visitor_passes_token_hash_format"
  CHECK ("token_hash" ~ '^[0-9a-f]{64}$');
ALTER TABLE "visitor_passes" ADD CONSTRAINT "visitor_passes_code_hash_format"
  CHECK ("code_hash" ~ '^[0-9a-f]{64}$');
CREATE UNIQUE INDEX "visitor_passes_one_live_per_invitation"
  ON "visitor_passes" ("invitation_id") WHERE "revoked_at" IS NULL;
CREATE UNIQUE INDEX "visitor_passes_live_code_per_property"
  ON "visitor_passes" ("property_id", "code_hash") WHERE "revoked_at" IS NULL;

-- A pass is never re-pointed or un-revoked; the only change allowed is revoking it once.
CREATE FUNCTION app_visitor_pass_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF OLD."revoked_at" IS NOT NULL
     OR NEW."revoked_at" IS NULL
     OR (NEW."organisation_id", NEW."property_id", NEW."invitation_id", NEW."token_hash", NEW."code_hash", NEW."created_at")
        IS DISTINCT FROM
        (OLD."organisation_id", OLD."property_id", OLD."invitation_id", OLD."token_hash", OLD."code_hash", OLD."created_at") THEN
    RAISE EXCEPTION 'visitor pass % can only be revoked, once', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "visitor_passes_guard"
  BEFORE UPDATE ON "visitor_passes"
  FOR EACH ROW EXECUTE FUNCTION app_visitor_pass_guard();

-- ---------------------------------------------------------------------------------------------
-- visits
-- ---------------------------------------------------------------------------------------------
ALTER TABLE "visits" ADD CONSTRAINT "visits_name_trimmed"
  CHECK ("visitor_name" = btrim("visitor_name") AND length("visitor_name") BETWEEN 1 AND 200);
ALTER TABLE "visits" ADD CONSTRAINT "visits_phone_e164"
  CHECK ("visitor_phone" IS NULL OR "visitor_phone" ~ '^\+[1-9][0-9]{6,14}$');
ALTER TABLE "visits" ADD CONSTRAINT "visits_plate_normalised"
  CHECK ("vehicle_plate" IS NULL OR "vehicle_plate" ~ '^[A-Z0-9-]{2,15}$');
ALTER TABLE "visits" ADD CONSTRAINT "visits_gate_trimmed"
  CHECK ("gate" IS NULL OR ("gate" = btrim("gate") AND length("gate") BETWEEN 1 AND 60));
-- A denial always has a reason; an admission never does; denied visitors never depart.
ALTER TABLE "visits" ADD CONSTRAINT "visits_decision_consistent"
  CHECK (("decision" = 'DENIED') = ("denial_reason" IS NOT NULL)
         AND ("denial_reason" IS NULL OR length(btrim("denial_reason")) BETWEEN 1 AND 500)
         AND ("decision" = 'ADMITTED' OR "departed_at" IS NULL));
ALTER TABLE "visits" ADD CONSTRAINT "visits_departure_consistent"
  CHECK (("departed_at" IS NULL) = ("departure_recorded_by_user_id" IS NULL)
         AND ("departed_at" IS NULL OR "departed_at" >= "arrived_at"));
-- A pass belongs to an invitation, and an invitation to a unit. unit_id must be set for the
-- composite invitation key to be checked (foreign keys skip rows with a NULL column).
ALTER TABLE "visits" ADD CONSTRAINT "visits_links_consistent"
  CHECK (("pass_id" IS NULL OR "invitation_id" IS NOT NULL)
         AND ("invitation_id" IS NULL OR "unit_id" IS NOT NULL));

-- Online admission backstop (the API checks first; this holds under concurrency):
--   * the decision is recorded now, not backdated into the window;
--   * the invitation is active and the arrival falls inside its window;
--   * the invitation still has entries left (row lock: two gates cannot both use the last one);
--   * the pass, if used, is live.
-- PAPER and OFFLINE_SYNC records describe what already happened and are stored as they are;
-- the API flags those that the invitation would not have allowed.
CREATE FUNCTION app_visit_admission_check() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
DECLARE
  inv record;
  used integer;
BEGIN
  IF NEW."source" <> 'ONLINE' OR NEW."decision" <> 'ADMITTED' OR NEW."invitation_id" IS NULL THEN
    RETURN NEW;
  END IF;
  IF abs(extract(epoch FROM (NEW."arrived_at" - now()))) > 300 THEN
    RAISE EXCEPTION 'online admission must be recorded at the time it happens'
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT "status", "valid_from", "valid_until", "max_entries" INTO inv
    FROM "visitor_invitations" WHERE "id" = NEW."invitation_id" FOR UPDATE;
  IF inv."status" <> 'ACTIVE' THEN
    RAISE EXCEPTION 'visitor invitation % is revoked', NEW."invitation_id"
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."arrived_at" < inv."valid_from" OR NEW."arrived_at" > inv."valid_until" THEN
    RAISE EXCEPTION 'visitor invitation % is not valid at this time', NEW."invitation_id"
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT count(*) INTO used FROM "visits"
   WHERE "invitation_id" = NEW."invitation_id" AND "decision" = 'ADMITTED';
  IF used >= inv."max_entries" THEN
    RAISE EXCEPTION 'visitor invitation % has no entries left', NEW."invitation_id"
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."pass_id" IS NOT NULL AND EXISTS (
    SELECT 1 FROM "visitor_passes" WHERE "id" = NEW."pass_id" AND "revoked_at" IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'visitor pass % is revoked', NEW."pass_id"
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "visits_admission_check"
  BEFORE INSERT ON "visits"
  FOR EACH ROW EXECUTE FUNCTION app_visit_admission_check();

-- A visit is a record of what happened: the only change allowed is recording the departure,
-- once. Corrections are new records (and the audit trail), never edits.
CREATE FUNCTION app_visit_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF OLD."departed_at" IS NOT NULL OR NEW."departed_at" IS NULL
     OR (NEW."organisation_id", NEW."property_id", NEW."unit_id", NEW."invitation_id", NEW."pass_id",
         NEW."category", NEW."visitor_name", NEW."visitor_phone", NEW."vehicle_plate", NEW."decision",
         NEW."denial_reason", NEW."gate", NEW."arrived_at", NEW."recorded_by_user_id", NEW."source",
         NEW."created_at")
        IS DISTINCT FROM
        (OLD."organisation_id", OLD."property_id", OLD."unit_id", OLD."invitation_id", OLD."pass_id",
         OLD."category", OLD."visitor_name", OLD."visitor_phone", OLD."vehicle_plate", OLD."decision",
         OLD."denial_reason", OLD."gate", OLD."arrived_at", OLD."recorded_by_user_id", OLD."source",
         OLD."created_at") THEN
    RAISE EXCEPTION 'visit % can only record its departure, once', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "visits_guard"
  BEFORE UPDATE ON "visits"
  FOR EACH ROW EXECUTE FUNCTION app_visit_guard();

-- ---------------------------------------------------------------------------------------------
-- access_events: append-only for every role, including the schema owner.
-- ---------------------------------------------------------------------------------------------
ALTER TABLE "access_events" ADD CONSTRAINT "access_events_gate_trimmed"
  CHECK ("gate" IS NULL OR ("gate" = btrim("gate") AND length("gate") BETWEEN 1 AND 60));

CREATE FUNCTION app_reject_access_event_modification() RETURNS trigger
  LANGUAGE plpgsql
  AS $$ BEGIN RAISE EXCEPTION 'access_events is append-only' USING ERRCODE = 'insufficient_privilege'; END $$;

CREATE TRIGGER "access_events_append_only"
  BEFORE UPDATE OR DELETE ON "access_events"
  FOR EACH ROW EXECUTE FUNCTION app_reject_access_event_modification();

CREATE TRIGGER "access_events_no_truncate"
  BEFORE TRUNCATE ON "access_events"
  FOR EACH STATEMENT EXECUTE FUNCTION app_reject_access_event_modification();

-- ---------------------------------------------------------------------------------------------
-- Row-level security: tenant context only (MULTI_TENANCY section 3.3).
-- ---------------------------------------------------------------------------------------------
DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['visitor_invitations', 'visitor_passes', 'visits', 'access_events'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR SELECT USING (organisation_id = app_current_organisation_id())', t || '_select', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR INSERT WITH CHECK (organisation_id = app_current_organisation_id())', t || '_insert', t);
  END LOOP;
  FOREACH t IN ARRAY ARRAY['visitor_invitations', 'visitor_passes', 'visits'] LOOP
    EXECUTE format('CREATE POLICY %I ON %I FOR UPDATE USING (organisation_id = app_current_organisation_id()) WITH CHECK (organisation_id = app_current_organisation_id())', t || '_update', t);
  END LOOP;
END
$$;

-- ---------------------------------------------------------------------------------------------
-- Least privilege: no DELETE anywhere; the access log is insert-only.
-- ---------------------------------------------------------------------------------------------
REVOKE ALL ON "visitor_invitations", "visitor_passes", "visits", "access_events" FROM PUBLIC;
GRANT SELECT, INSERT, UPDATE ON "visitor_invitations", "visitor_passes", "visits" TO veyra_app;
GRANT SELECT, INSERT ON "access_events" TO veyra_app;
